 if (select md5(string_agg(entry_id||'|'||entity_id||'|'||role,E'\n' order by entry_id collate "C",entity_id collate "C",role collate "C")) from public.entry_credits where catalogue_id='football-clubs-2026-10-28-v1')<>'212ee826845bb68bf299f45723e1a2bb' then raise exception 'football_relationship_signature_mismatch'; end if;
