 if (select count(*) from public.opening_pool_entries where pool_id='movies-familiar-2026-10-28-v1')<>55 or (select md5(string_agg(entry_id,E'\n' order by entry_id collate "C")) from public.opening_pool_entries where pool_id='movies-familiar-2026-10-28-v1')<>'6785cf20d39eab9ff1ebd1547d5d917c' then raise exception 'opening_pool_signature_mismatch'; end if;
 if exists(select 1 from public.opening_pool_entries pe join public.entries e on e.catalogue_id=pe.catalogue_id and e.id=pe.entry_id where pe.pool_id='movies-familiar-2026-10-28-v1' and (not e.seed_eligible or not game_private.has_opening(pe.catalogue_id,pe.entry_id))) then raise exception 'unplayable_familiar_seed'; end if;
