 if exists(select 1 from public.opening_pool_entries pe join public.entries e on e.catalogue_id=pe.catalogue_id and e.id=pe.entry_id where pe.pool_id='football-familiar-2026-10-28-v1' and (not e.seed_eligible or not game_private.has_opening(pe.catalogue_id,pe.entry_id))) then raise exception 'unplayable_familiar_seed'; end if;
 update public.catalogues set published=true where id='football-clubs-2026-10-28-v1' and not published;
